"""Generate a Russian report from validated measurements only."""
import argparse
import json
from pathlib import Path
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from analyze import validate, digest


def create_report(results, output):
    results = Path(results)
    summary = validate(results)
    saved = json.loads((results / 'summary.json').read_text(encoding='utf-8'))
    for key in ['rows', 'evidence_sha256', 'commit']:
        if saved[key] != summary[key]:
            raise ValueError('Stale plots or evidence. Run analyze.py --plots again.')
    for name in ['complexity.png', 'speedup.png']:
        if saved['chart_sha256'][name] != digest(results / name):
            raise ValueError('Plot changed. Rebuild plots.')
    rows, ctx = summary['rows'], summary['context']
    d = Document()
    sec = d.sections[0]
    sec.page_width, sec.page_height = Cm(21), Cm(29.7)
    sec.left_margin, sec.right_margin = Cm(3), Cm(1.5)
    sec.top_margin = sec.bottom_margin = Cm(2)
    for name in ['Normal', 'Title', 'Heading 1', 'Heading 2']:
        d.styles[name].font.name = 'Times New Roman'
        d.styles[name].font.color.rgb = RGBColor(0, 0, 0)
    d.styles['Normal'].font.size = Pt(12)
    d.styles['Normal'].paragraph_format.line_spacing = 1.15
    d.styles['Normal'].paragraph_format.space_after = Pt(6)
    sec.different_first_page_header_footer = True
    footer = sec.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    field = OxmlElement('w:fldSimple')
    field.set(qn('w:instr'), 'PAGE')
    footer._p.append(field)
    def para(text):
        return d.add_paragraph(text)
    for line in ['\u0421\u0438\u0431\u0438\u0440\u0441\u043a\u0438\u0439 \u0444\u0435\u0434\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0438\u0442\u0435\u0442',
                 '\u0418\u043d\u0441\u0442\u0438\u0442\u0443\u0442 \u043a\u043e\u0441\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0438 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439']:
        para(line).alignment = WD_ALIGN_PARAGRAPH.CENTER
    d.add_paragraph()
    d.add_paragraph('\u041f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u0430\u044f \u0440\u0435\u0434\u0443\u043a\u0446\u0438\u044f \u0432\u0435\u043a\u0442\u043e\u0440\u0430 \u043d\u0430 GPU', style='Title')
    para('\u041f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u2116 5')
    para('\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u043b\u0438: \u0410.\u0410. \u041f\u043b\u0430\u0442\u043e\u043d\u043e\u0432, \u041d.\u0421. \u0411\u0443\u0447\u0435\u043d\u0438\u043a')
    para('\u0413\u0440\u0443\u043f\u043f\u0430: \u041a\u041823-06\u0411')
    para('\u041f\u0440\u0435\u043f\u043e\u0434\u0430\u0432\u0430\u0442\u0435\u043b\u044c: \u0421.\u0410. \u0422\u0430\u0440\u0430\u0441\u043e\u0432')
    para('\u041a\u0440\u0430\u0441\u043d\u043e\u044f\u0440\u0441\u043a, 2026')
    d.add_page_break()
    d.add_heading('1 \u0426\u0435\u043b\u044c \u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f', level=1)
    para('\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0434\u0432\u0430 \u0441\u043f\u043e\u0441\u043e\u0431\u0430 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0441\u0443\u043c\u043c\u044b \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0432\u0435\u043a\u0442\u043e\u0440\u0430 \u043d\u0430 GPU: \u0434\u0435\u0440\u0435\u0432\u043e \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u044f\u0435\u043c\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438 \u0438 \u0440\u0435\u0434\u0443\u043a\u0446\u0438\u044f \u0441 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0435\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 __shfl_down_sync. \u0412\u044b\u0432\u043e\u0434\u044b \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u044b \u043d\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u044b\u0445 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f\u0445 \u0434\u0430\u043d\u043d\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.')
    para('\u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439: https://github.com/NikitaBuchenik/hsys/tree/main/work5')
    para('\u0412\u0435\u0440\u0441\u0438\u044f \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u043e\u0432: ' + summary['commit'])
    para('\u041e\u0434\u0438\u043d \u0431\u043b\u043e\u043a \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 256 \u043d\u0438\u0442\u0435\u0439 \u0438 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0434\u043e 512 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432: \u043a\u0430\u0436\u0434\u0430\u044f \u043d\u0438\u0442\u044c \u0441\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442 \u043d\u0435 \u0431\u043e\u043b\u0435\u0435 \u0434\u0432\u0443\u0445 \u0432\u0445\u043e\u0434\u043e\u0432. \u0425\u0432\u043e\u0441\u0442 \u0434\u043e\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0443\u043b\u044f\u043c\u0438. \u041f\u0435\u0440\u0432\u044b\u0439 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c \u0441\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 256 \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u044b\u0445 \u0441\u0443\u043c\u043c \u0432 shared memory \u0441 \u0431\u0430\u0440\u044c\u0435\u0440\u0430\u043c\u0438 \u0431\u043b\u043e\u043a\u0430. \u0412\u0442\u043e\u0440\u043e\u0439 \u0441\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0432\u043d\u0443\u0442\u0440\u0438 \u043f\u043e\u043b\u043d\u044b\u0445 \u0432\u0430\u0440\u043f\u043e\u0432, \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442 8 \u0441\u0443\u043c\u043c \u0432\u0430\u0440\u043f\u043e\u0432 \u0432 shared memory \u0438 \u0441\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0438\u0445 \u043f\u0435\u0440\u0432\u044b\u043c \u0432\u0430\u0440\u043f\u043e\u043c.')
    para('\u041a\u0430\u0436\u0434\u044b\u0439 \u0431\u043b\u043e\u043a \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0441\u0443\u043c\u043c\u0443 \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u044d\u043b\u0435\u043c\u0435\u043d\u0442 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438. \u0421\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0438 \u0442\u043e\u0433\u043e \u0436\u0435 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0441\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044e\u0442 \u044d\u0442\u0438 \u0441\u0443\u043c\u043c\u044b \u0434\u043e \u043e\u0434\u043d\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430. \u0412\u0441\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u044b \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u044e\u0442\u0441\u044f \u0432 \u043e\u0434\u043d\u043e\u043c \u043f\u043e\u0442\u043e\u043a\u0435 CUDA. \u0410\u0442\u043e\u043c\u0430\u0440\u043d\u043e\u0435 \u0441\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0438 \u0441\u0443\u043c\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u043d\u0430 CPU \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f.')
    para('VectorView \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u043f\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044e \u0438 \u043d\u0435 \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u043f\u0430\u043c\u044f\u0442\u044c\u044e. DeviceBuffer \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0430\u0435\u0442 GPU-\u043f\u0430\u043c\u044f\u0442\u044c \u043f\u043e RAII. \u041a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u043f\u0440\u0435\u0449\u0435\u043d\u043e, \u043f\u0435\u0440\u0435\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0432\u043b\u0430\u0434\u0435\u043d\u0438\u0435. ReductionWorkspace \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f. \u0412\u0445\u043e\u0434, \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0435 \u0441\u0443\u043c\u043c\u044b \u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0438\u043c\u0435\u044e\u0442 \u0442\u0438\u043f float.')
    d.add_heading('2 \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438', level=1)
    para('\u041f\u0440\u043e\u0439\u0434\u0435\u043d\u043e 24 \u0442\u0435\u0441\u0442\u0430 \u0431\u0435\u0437 \u043e\u0448\u0438\u0431\u043e\u043a \u0438 \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043e\u0432. 16 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0441\u043b\u0443\u0447\u0430\u0435\u0432 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442 \u043e\u0431\u0430 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0434\u043b\u044f n = 1, 2, 3, 127, 129, 512, 541, 1037. \u041a\u0430\u0436\u0434\u044b\u0439 \u0441\u043b\u0443\u0447\u0430\u0439 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043f\u044f\u0442\u044c \u043d\u0430\u0431\u043e\u0440\u043e\u0432: \u043d\u0443\u043b\u0438, \u0435\u0434\u0438\u043d\u0438\u0446\u044b, \u0434\u0432\u043e\u0438\u0447\u043d\u044b\u0435 \u0434\u0440\u043e\u0431\u0438, \u0447\u0435\u0440\u0435\u0434\u0443\u044e\u0449\u0438\u0435\u0441\u044f \u0437\u043d\u0430\u043a\u0438 \u0438 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0435 \u0434\u0440\u043e\u0431\u0438. \u042d\u0442\u0430\u043b\u043e\u043d \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u0435\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 Eigen::Matrix::sum; EXPECT_NEAR \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0439 \u0434\u043e\u043f\u0443\u0441\u043a 1e-4.')
    para('\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u043f\u0443\u0441\u0442\u043e\u0439 \u0432\u0435\u043a\u0442\u043e\u0440, \u0433\u0440\u0430\u043d\u0438\u0446\u044b \u0432\u0430\u0440\u043f\u0430 \u0438 \u0431\u043b\u043e\u043a\u0430, \u0431\u043e\u043b\u0435\u0435 \u0434\u0432\u0443\u0445 \u043f\u0440\u043e\u0445\u043e\u0434\u043e\u0432, \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u0447\u0430\u0441\u0442\u044f\u043c\u0438 \u0441 \u0445\u0432\u043e\u0441\u0442\u043e\u043c, \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u0438, \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0435 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u044b \u0438 \u0432\u043b\u0430\u0434\u0435\u043d\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u044c\u044e. \u0414\u043e\u043f\u0443\u0441\u043a \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u043a \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u043c \u0432\u0445\u043e\u0434\u0430\u043c: \u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u043b\u044c\u043d\u043e\u0433\u043e \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u0447\u0438\u0441\u0435\u043b \u0442\u0430\u043a\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f.')
    d.add_page_break()
    d.add_heading('3 \u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u044b \u043a\u043e\u0434\u0430', level=1)
    code = (results / 'source/core/src/reduction.cu').read_text(encoding='utf-8-sig')
    for name in ['warp_sum', 'kernel_vecred_nobr', 'kernel_vecred_br']:
        start = code.index(('__device__ float ' if name == 'warp_sum' else '__global__ void ') + name)
        brace = code.index('{', start)
        depth, end = 1, brace + 1
        while depth:
            depth += (code[end] == '{') - (code[end] == '}')
            end += 1
        d.add_heading(name.replace('_', ' '), level=2)
        for line in code[start:end].splitlines():
            p = para(line)
            p.paragraph_format.space_after = Pt(0)
            p.paragraph_format.line_spacing = 1.0
            for run in p.runs:
                run.font.name = 'Consolas'
                run.font.size = Pt(9)
    d.add_page_break()
    d.add_heading('4 \u041c\u0435\u0442\u043e\u0434\u0438\u043a\u0430 \u0438 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u0435', level=1)
    for key in ['gpu', 'compute_capability', 'cuda_driver', 'cuda_runtime', 'gpu_memory_bytes', 'date']:
        para(key + ': ' + str(ctx.get(key, '\u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u043e')))
    for name in ['cpu.txt', 'os.txt', 'nvcc.txt']:
        para(' '.join((results / name).read_text(encoding='utf-8-sig').split()))
    para('Google Benchmark \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u043f\u043e 5 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u0434\u043b\u044f \u043e\u0431\u043e\u0438\u0445 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u043e\u0432 \u043d\u0430 \u0432\u0441\u0435\u0445 29 \u0440\u0430\u0437\u043c\u0435\u0440\u0430\u0445 n = 8 \xd7 2^e, e \u043e\u0442 0 \u0434\u043e 28. \u0414\u043e \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0439 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u044e\u0442\u0441\u044f 3 \u043f\u0440\u043e\u0433\u0440\u0435\u0432\u0430. \u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u043c\u043e\u0435 GPU-\u0432\u0440\u0435\u043c\u044f \u043f\u043e\u0432\u0442\u043e\u0440\u0430 \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 0,05 \u0441. \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f CUDA Events \u0438 UseManualTime. \u0418\u0437\u043c\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u0432\u0441\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u044b \u0440\u0435\u0434\u0443\u043a\u0446\u0438\u0438, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044f \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u0435, \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0443 \u0438 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0445. \u041e\u0442\u0432\u0435\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u0438 \u043f\u043e\u0441\u043b\u0435 \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u043c\u043e\u0433\u043e \u0446\u0438\u043a\u043b\u0430.')
    cap = int(ctx['chunk_capacity_elements'])
    para(f'\u0401\u043c\u043a\u043e\u0441\u0442\u044c \u0432\u0445\u043e\u0434\u043d\u043e\u0433\u043e \u0431\u0443\u0444\u0435\u0440\u0430: {cap} \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 ({cap * 4 / 2**20:g} \u041c\u0438\u0411). \u041c\u0435\u043d\u044c\u0448\u0438\u0435 \u0432\u0445\u043e\u0434\u044b \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043d\u0430 GPU (resident). \u0411\u043e\u043b\u044c\u0448\u0438\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u044e\u0442\u0441\u044f \u0447\u0430\u0441\u0442\u044f\u043c\u0438 (streamed); \u0441\u0443\u043c\u043c\u044b \u0447\u0430\u0441\u0442\u0435\u0439 \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u044f\u044e\u0442\u0441\u044f \u043d\u0430 GPU, \u0432\u0440\u0435\u043c\u044f \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u044f \u0443\u0447\u0442\u0435\u043d\u043e. \u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u0435\u043a\u0442\u043e\u0440 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 2 147 483 648 float-\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432, \u0442\u043e \u0435\u0441\u0442\u044c 8 \u0413\u0438\u0411, \u0438 \u043d\u0435 \u043f\u043e\u043c\u0435\u0449\u0430\u0435\u0442\u0441\u044f \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u043d\u0430 GPU \u0441 6 \u0413\u0438\u0411.')
    para('\u041b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0432\u0435\u043a\u0442\u043e\u0440 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u043e\u0439 x[i] = ((i mod 257) - 128) / 256. \u041e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0432\u0441\u0435 n \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432. \u041d\u0443\u043b\u0435\u0432\u0430\u044f \u0441\u0443\u043c\u043c\u0430 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430 \u0434\u0430\u0451\u0442 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u0443\u044e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 \u043e\u0442\u0432\u0435\u0442\u0430 \u0431\u0435\u0437 \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u044f 8 \u0413\u0438\u0411 \u043d\u0430 CPU. \u0422\u0435\u0441\u0442\u044b \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u0434\u0440\u0443\u0433\u0438\u0435 \u043d\u0430\u0431\u043e\u0440\u044b \u0434\u0430\u043d\u043d\u044b\u0445.')
    para('\u0420\u0435\u0436\u0438\u043c\u044b resident \u0438 streamed \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u044b \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u043e. \u0414\u043b\u044f streamed \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0441\u0443\u043c\u043c\u0430 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u043e\u0432, \u0430 \u043d\u0435 \u043f\u043e\u043b\u043d\u0430\u044f \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u0441 PCIe. \u041a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043c\u0435\u0436\u0434\u0443 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0430\u043c\u0438 \u043c\u043e\u0433\u0443\u0442 \u043c\u0435\u043d\u044f\u0442\u044c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043a\u0435\u0448\u0435\u0439. \u041e\u0431\u0430 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0447\u0430\u0441\u0442\u0438 \u0438 \u0432\u0445\u043e\u0434\u044b. \u041f\u043e\u043b\u043e\u0441\u044b min/max \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0430\u043c\u0438.')
    for begin in range(0, len(rows), 15):
        d.add_page_break()
        d.add_heading('5 \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0439' if begin == 0 else '\u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432', level=1)
        table = d.add_table(rows=1, cols=5)
        table.style = 'Table Grid'
        table.autofit = False
        widths = [3.2, 2.7, 2.7, 2.2, 5.7]
        for column, width in zip(table.columns, widths):
            column.width = Cm(width)
        for cell, text in zip(table.rows[0].cells, ['n', 'Shared \u043c\u043a\u0441', 'Shuffle \u043c\u043a\u0441', '\u0423\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435', '\u0420\u0435\u0436\u0438\u043c \u0438 \u0447\u0430\u0441\u0442\u0438']):
            cell.text = text
        table.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
        for row in rows[begin:begin + 15]:
            values = [str(row['n']), f"{row['Shared_seconds'] * 1e6:.3f}", f"{row['Shuffle_seconds'] * 1e6:.3f}", f"{row['speedup']:.3f}", f"{row['mode']}, {row['chunks']}"]
            for cell, value, width in zip(table.add_row().cells, values, widths):
                cell.text = value
                cell.width = Cm(width)
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    p.paragraph_format.space_after = Pt(4)
                    p.paragraph_format.line_spacing = 1.0
                    for run in p.runs:
                        run.font.size = Pt(10)
        para('\u041c\u0435\u0434\u0438\u0430\u043d\u044b \u043f\u044f\u0442\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432. \u0423\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435 = \u0432\u0440\u0435\u043c\u044f Shared / \u0432\u0440\u0435\u043c\u044f Shuffle. \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 1 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e Shuffle.')
    d.add_page_break()
    d.add_heading('6 \u0413\u0440\u0430\u0444\u0438\u043a\u0438', level=1)
    for name, caption in [('complexity.png', '\u0420\u0438\u0441\u0443\u043d\u043e\u043a 1 - \u0412\u0440\u0435\u043c\u044f \u043f\u043e\u043b\u043d\u043e\u0439 \u0440\u0435\u0434\u0443\u043a\u0446\u0438\u0438'), ('speedup.png', '\u0420\u0438\u0441\u0443\u043d\u043e\u043a 2 - \u0423\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435 Shuffle')]:
        d.add_picture(str(results / name), width=Cm(16))
        para(caption)
    d.add_page_break()
    d.add_heading('7 \u0410\u043d\u0430\u043b\u0438\u0437 \u0438 \u0432\u044b\u0432\u043e\u0434\u044b', level=1)
    for mode in ['resident', 'streamed']:
        subset = [row for row in rows if row['mode'] == mode]
        if not subset:
            continue
        best = max(subset, key=lambda row: row['speedup'])
        last = subset[-1]
        separated = [str(row['n']) for row in subset if row['Shuffle_max'] < row['Shared_min']]
        para(f"\u0420\u0435\u0436\u0438\u043c {mode}: \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u043c\u0435\u0434\u0438\u0430\u043d {best['speedup']:.3f} \u043f\u0440\u0438 n={best['n']}. \u041d\u0430 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u0440\u0435\u0436\u0438\u043c\u0430 n={last['n']} \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0440\u0430\u0432\u043d\u043e {last['speedup']:.3f}.")
        para('\u0414\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u044b \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u044b \u0432 \u043f\u043e\u043b\u044c\u0437\u0443 Shuffle \u0434\u043b\u044f n: ' + (', '.join(separated) if separated else '\u0442\u0430\u043a\u0438\u0445 \u0442\u043e\u0447\u0435\u043a \u043d\u0435\u0442') + '. \u041f\u0440\u0438 \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0442\u0438\u0438 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u043e\u0432 \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u0443\u044e \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u043c\u0435\u0434\u0438\u0430\u043d \u043d\u0435 \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u043c \u043a\u0430\u043a \u0443\u0431\u0435\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435.')
    para('\u041e\u0431\u0430 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u044e\u0442 \u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0435 \u043f\u043e n \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0440\u0430\u0431\u043e\u0442\u044b. \u0414\u0435\u0440\u0435\u0432\u043e \u0438\u043c\u0435\u0435\u0442 \u043b\u043e\u0433\u0430\u0440\u0438\u0444\u043c\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0433\u043b\u0443\u0431\u0438\u043d\u0443, \u043d\u043e \u0435\u0451 \u043d\u0435\u043b\u044c\u0437\u044f \u043e\u0442\u043e\u0436\u0434\u0435\u0441\u0442\u0432\u043b\u044f\u0442\u044c \u0441 \u0432\u0440\u0435\u043c\u0435\u043d\u0435\u043c \u043d\u0430 GPU \u0441 \u043a\u043e\u043d\u0435\u0447\u043d\u044b\u043c \u0447\u0438\u0441\u043b\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432. Shared \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 1024 \u0431\u0430\u0439\u0442\u0430 shared memory \u0438 9 \u0431\u0430\u0440\u044c\u0435\u0440\u043e\u0432 \u0431\u043b\u043e\u043a\u0430; Shuffle - 32 \u0431\u0430\u0439\u0442\u0430 \u0438 \u043e\u0434\u0438\u043d \u0431\u0430\u0440\u044c\u0435\u0440 \u0431\u043b\u043e\u043a\u0430, \u0430 \u043e\u0431\u043c\u0435\u043d \u0432\u043d\u0443\u0442\u0440\u0438 \u0432\u0430\u0440\u043f\u0430 \u0438\u0434\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b. \u042d\u0442\u043e \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0435\u0442 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e, \u043d\u043e \u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435 \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435.')
    para('\u041d\u0430 \u043c\u0430\u043b\u044b\u0445 \u0440\u0430\u0437\u043c\u0435\u0440\u0430\u0445 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b \u0437\u0430\u043f\u0443\u0441\u043a\u0438 \u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0445\u043e\u0434\u043e\u0432, \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u043c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435\u043c \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043d\u0430\u044f \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u043f\u0430\u043c\u044f\u0442\u0438. \u042d\u0442\u043e \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 \u0431\u0435\u0437 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0444\u0438\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f. \u041d\u0430 \u0433\u0440\u0430\u043d\u0438\u0446\u0435 streamed \u043f\u043e\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0438 \u0438 \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435 \u0447\u0430\u0441\u0442\u0435\u0439, \u0447\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0434\u0430\u0432\u0430\u0442\u044c \u0438\u0437\u043b\u043e\u043c \u0433\u0440\u0430\u0444\u0438\u043a\u0430.')
